@@ -0,0 +1,4 @@
+export type Permission = { granted: boolean; expiresAt: number; candidateId: string };
+export function mayPublish(p: Permission, candidateId: string, now: number) {
+  return p.granted && p.candidateId === candidateId && p.expiresAt > now;
+}
